const setMode = (m) => { localStorage.setItem('todoban.glow', m); document.documentElement.dataset.glow = m; };
const measure = async (ms, during) => {
  await window.todoban.perfMetrics();
  const frames = []; let last = performance.now(); let on = true;
  const tick = (t) => { frames.push(t - last); last = t; if (on) requestAnimationFrame(tick); };
  requestAnimationFrame(tick);
  const stop = during ? during() : null;
  await new Promise(r => setTimeout(r, ms));
  on = false; if (stop) stop();
  const m = await window.todoban.perfMetrics();
  const sum = (type) => Number(m.filter(x => x.type === type).reduce((a, x) => a + x.cpu, 0).toFixed(1));
  const f = frames.slice(2).sort((a, b) => a - b);
  const p = (q) => Number(f[Math.floor(q * (f.length - 1))].toFixed(1));
  return { gpu: sum('GPU'), renderer: sum('Tab'), main: sum('Browser'), fps: Math.round(frames.length / (ms / 1000)), p95: p(0.95), over20ms: f.filter(x => x > 20).length };
};
setMode('static'); await new Promise(r => setTimeout(r, 300)); return await measure(5000);

